// Thornmarch service worker — GENERATED by scripts/build.mjs from the parts in pwa/sw/. Edit the parts, never the output.
//
// What it does:
//   · INSTALL    downloads the whole game (every page, script, style, image, font, data file) into ONE cache named after the
//                build, then WAITS. It does not take over by itself: the player is asked first (see public/js/pwa/).
//   · ACTIVATE   deletes the caches of older builds, takes control of open pages.
//   · FETCH      pages and files come from that cache first (so the game opens instantly and offline); music is cached the
//                first time it is played; the multiplayer socket, the statistics API and the dashboard are never touched.
//   · MESSAGE    "skip waiting" (take over now) and "which build are you?" from the page.

// Values the build fills in (scripts/lib/serviceWorker.mjs replaces each __AEII_*__ with JSON):
const VERSION = __AEII_VERSION__; // this build's cache: 'aeii-<hash of the shipped files>'
const BUILD = __AEII_BUILD__; // human version, e.g. '2.1.0+29bc1d705f'
const NOTE = __AEII_NOTE__; // optional one-line release note shown in the update banner
const MEDIA = __AEII_MEDIA__; // the music cache, named after the audio files: survives code-only releases
const PRECACHE = __AEII_PRECACHE__; // every URL downloaded at install
const MSG = __AEII_MESSAGES__; // message names shared with the page (public/js/pwa/protocol.js)
const CACHE_PREFIX = __AEII_CACHE_PREFIX__;

const MEDIA_PATH = '/assets/audio/';
const NEVER_PATHS = ['/ws', '/healthz', '/csp-report', '/version.json', '/sw.js'];
const NEVER_PREFIXES = ['/api/', '/admin/'];
